func (v semver) atLeast(other semver) bool {
	for i := range v {
		if i >= len(other) {
			break
		}
		if v[i] < other[i] {
			return false
		}
		if v[i] > other[i] {
			return true
		}
	}
	for i := len(v); i < len(other); i++ {
		if other[i] > 0 {
			return false
		}
	}
	return true
}
